-- ============================================================================
-- supply: Terminals, Depots & Fuel Supply joins the catalogue, the FIRST course
-- of the Supply Chain & Logistics module.
--
-- Catalogue row (module 'supply_chain', the academy module the lead ruled for
-- it on 2026-09-19; path_order 50, directly above the two Commercial & Trading
-- courses cut in the same wave, crude at 48 and refinery at 49; prereq_slug
-- NULL, the carried-over answer "no hard prerequisite inside a module"; school
-- left at its default, as every Facilities, Economics and Assurance course
-- leaves it, so the fees are the published school-level rows) plus the three
-- capstones and their eighteen graded fields, generated by
-- tools/course-waves/supply/gen_course.py from fields.json, precision.json and
-- capstone.json, which supply_capstone.mjs writes from the capstone records in
-- supply_fields_capstone.mjs through the vendored engines. The three tier
-- structures (78 lesson keys) and the 396 questions are the three deep seeds;
-- the go-live is a fifth migration and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/supply AND the Suite production
-- upload carrying Suite main 1a71d9c90 (Suite #540: the Terminal & Depot page
-- repairs this course teaches, and the engines at 13f0936 that page and the
-- Fuel Pricing page run on) is live. This file does not depend on crude or
-- refinery: any of the three may be seeded first.
--
-- THE ONE SENTENCE THE COURSE IS. A terminal's stock, a cargo's cost and a
-- litre's pump price are each a chain of measured inputs walked in a stated
-- order, and the engine refuses or names every link nobody measured instead of
-- assuming it, because a figure that cannot come out wrong proves nothing.
--
-- THE ENGINES. engines/downstream/terminalDepot.js and fuelPricing.js,
-- vendored sha-identical with engines 13f0936 (MD3-2); the recon findings on
-- the graded paths were repaired upstream in MD3-0 and MD3-1.
--
-- EVERY GRADED FIELD IS A NUMBER THE ENGINE RETURNS, at full precision, graded
-- at ONE UNIT IN THE LAST PLACE THE PROMPT ASKS FOR: m3, minutes, days, dollars
-- and the exchange rate to two decimals at 0.01; the probability of waiting and
-- the naira-a-litre figures to four at 0.0001; the truck count, the one whole
-- number, at 0.5. The engine itself rounds CIF and the landed total to the cent
-- and the per-litre prices to four decimals, so a correct reading can sit half
-- a unit from the stored value on each side. The grader
-- (academy_submit_capstone) casts expected, tol and answer to numeric and
-- accepts |answer - expected| <= tol. No verdict, direction or refusal is
-- graded. No field reads a date or a clock.
--
-- THE PROMPTS are capstone.json's, verbatim: every condition a field needs and
-- the precision it is graded at, and nothing that hands over an answer. No
-- graded value of any tier is a number in any prompt, within its tolerance or
-- as its own rounding, and none of the engine-derived intermediates (the water
-- volumes, the closing dip, the offered load, the cycle, the trips a day, C&F,
-- the outturn, the dollar cost a litre) is printed in any rounding of three or
-- more significant figures. No graded value is within its tolerance of any
-- number the teaching digest prints, and no two graded values are within the
-- looser of their tolerances.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('supply', 'Terminals, Depots & Fuel Supply', 'supply_chain', 50, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'supply', 'beginner', 'associate',
  'OKOMU, an inland depot of an invented operator: two tanks dipped one morning, and the day they close',
  'Two dips and the day closed',
  'OKOMU DEPOT, Ologbo Energy Depots Ltd (an invented record). Tank OK-1 is a vertical AGO tank whose strapping table starts at the empty tank (0 mm, 0.000 m3) and is linear between entries; the entries either side of this morning''s dip are 8400 mm 2282.417 m3 and 8600 mm 2336.761 m3, and either side of the water cut 0 mm 0.000 m3 and 200 mm 54.343 m3. Dip 8437 mm, water cut 143 mm, VCF 0.9868 read off the depot''s own tables. Tank OK-2 is a horizontal PMS bullet whose table also starts at the empty tank; the entries either side of the dip are 2200 mm 94.464 m3 and 2300 mm 99.354 m3, and either side of the water cut 0 mm 0.000 m3 and 100 mm 1.171 m3. Dip 2265 mm, water cut 38 mm, VCF 0.9811 off the same tables. The day, all at standard: yesterday''s closing stock 2498.45 m3, receipts 1180 m3, deliveries 1352.6 m3, known losses 1.4 m3; the closing dip is the two tanks'' standard volumes together; the tolerance is 0.18 percent of throughput. Give six numbers in m3, each to two decimals, a loss as a negative number. (1) OK-1''s gross observed volume. (2) OK-1''s standard volume. (3) OK-2''s standard volume. (4) The expected closing stock. (5) The unaccounted figure. (6) The tolerance.',
  jsonb_build_array(
    jsonb_build_object('key','okomu_t1_gross_m3', 'label','OK-1 gross observed volume', 'unit','m3', 'expected',2253.615395, 'tol',0.01),
    jsonb_build_object('key','okomu_t1_standard_m3', 'label','OK-1 standard volume', 'unit','m3', 'expected',2223.867671786, 'tol',0.01),
    jsonb_build_object('key','okomu_t2_standard_m3', 'label','OK-2 standard volume', 'unit','m3', 'expected',95.360486872, 'tol',0.01),
    jsonb_build_object('key','okomu_expected_closing_m3', 'label','Expected closing stock of the day', 'unit','m3', 'expected',2324.45, 'tol',0.01),
    jsonb_build_object('key','okomu_unaccounted_m3', 'label','Unaccounted figure of the day, a loss as a negative number', 'unit','m3', 'expected',-5.221841342000062, 'tol',0.01),
    jsonb_build_object('key','okomu_tolerance_m3', 'label','Tolerance of the day', 'unit','m3', 'expected',4.55868, 'tol',0.01)
  )
),
(
  'supply', 'intermediate', 'professional',
  'OGWASHI, a depot of an invented operator: its loading rack, its tank farm, and the truck lane to its stations',
  'The rack, the farm and the lane',
  'OGWASHI DEPOT, Anioma Fuel Logistics Ltd (an invented record). The loading rack: trucks arrive at random at 14 an hour, a load takes 26 minutes on average, and there are 7 bays. The tank farm: OG-1 (PMS) capacity 6200 m3, heel 180 m3, stock 4127.5 m3; OG-2 (PMS) capacity 4400 m3, heel 140 m3, stock 18.6 m3; OG-3 (AGO) capacity 2800 m3, heel 92 m3, stock 1873.9 m3. The farm''s liftings are 1760 m3 a day, and it receives 1240 m3 a day by pipeline. The lane to its stations, every cost in naira and invented for the course: 238 km each way, a 42000 litre payload, 43 km/h average, 1.75 h to load, 1.25 h to discharge, 2.5 h queueing, diesel at 41 litres per 100 km and 1285 a litre, driver 72500 a trip, maintenance 52 and tyres 31 a km, tolls and levies 33500 a trip, overhead 46000 a trip, a truck costing 118000000 over 7 years, 14 working hours a day and 310 days a year, a transit loss of 0.25 percent. The stations take 2350000 litres a day. Give six numbers. (1) The probability that an arriving truck waits for a bay, to four decimals. (2) The mean wait for a bay in minutes, to two decimals. (3) The farm''s pumpable stock in m3, to two decimals. (4) The farm''s days of cover on its liftings, to two decimals. (5) The lane''s cost per litre delivered in naira, to four decimals. (6) The number of trucks the lane needs, a whole number.',
  jsonb_build_array(
    jsonb_build_object('key','ogwashi_rack_probability_of_waiting', 'label','Probability that an arriving truck waits for a bay', 'unit','probability', 'expected',0.6366683941275083, 'tol',0.0001),
    jsonb_build_object('key','ogwashi_rack_mean_wait_min', 'label','Mean wait for a bay', 'unit','minutes', 'expected',17.735762407837736, 'tol',0.01),
    jsonb_build_object('key','ogwashi_pumpable_stock_m3', 'label','Pumpable stock of the farm', 'unit','m3', 'expected',5729.4, 'tol',0.01),
    jsonb_build_object('key','ogwashi_days_of_cover', 'label','Days of cover on the liftings', 'unit','days', 'expected',3.2553409090909087, 'tol',0.01),
    jsonb_build_object('key','ogwashi_cost_per_litre_delivered_ngn', 'label','Cost of the lane per litre delivered', 'unit','naira a litre', 'expected',12.093276, 'tol',0.0001),
    jsonb_build_object('key','ogwashi_trucks_required', 'label','Trucks the lane needs', 'unit','trucks', 'expected',67, 'tol',0.5)
  )
),
(
  'supply', 'advanced', 'expert',
  'ORON, an AGO cargo landed at an invented jetty and priced to the nozzle against a price cap',
  'The cargo, the litre and the cap',
  'ORON JETTY, Cross River Estuary Energy Ltd (an invented record). An AGO cargo of 28500 tonnes at 838.2 kg/m3, FOB 742.5 USD a tonne, ocean loss 0.35 percent, 1487.6 naira to the dollar. Every rate is INVENTED for the course and none is a published figure: Ocean freight 31.4 USD per tonne; Marine insurance 0.175 percent of CIF; Import duty 6.25 percent of CIF; Port and harbour charges 2.85 USD per tonne; Regulatory and inspection charges 0.0019 USD per litre; Jetty throughput and discharge 1.35 USD per m3; Storage and handling 2.1 USD per m3; Financing and letter of credit 1.25 percent of CIF; Demurrage provision 48000 USD for the cargo. Freight builds C&F, insurance builds CIF, and every other line is levied on landing; a percent-of-CIF insurance is part of the value it is charged on. The pump build-up starts from the landed cost per litre sold as the app carries it, to four decimals, and adds in order, every element invented: Depot and terminal margin (Terminal) 18.5 naira a litre; Bridging or equalisation (Chain) 26 naira a litre; Transport to station (Transporter) 22.75 naira a litre; Marketer margin (Marketer) 17.25 naira a litre; Dealer margin (Dealer) 29.5 naira a litre; Statutory levies at the pump (Government) 8.4 naira a litre; Value added tax (Government) 5.5 percent of the running total. The price cap is 1390 naira a litre. Give six numbers. (1) CIF in USD, to two decimals. (2) The landed total in USD, to two decimals. (3) The landed cost per litre sold in naira, to four decimals. (4) The pump price in naira a litre, to four decimals. (5) The government''s share of that price in naira a litre, to four decimals. (6) The exchange rate, searched between 1200 and 1800 naira to the dollar, at which the pump price meets the cap, to two decimals.',
  jsonb_build_array(
    jsonb_build_object('key','oron_cif_usd', 'label','CIF value of the cargo', 'unit','USD', 'expected',22094815.93, 'tol',0.01),
    jsonb_build_object('key','oron_landed_total_usd', 'label','Landed total of the cargo', 'unit','USD', 'expected',24063059.78, 'tol',0.01),
    jsonb_build_object('key','oron_landed_per_litre_ngn', 'label','Landed cost per litre sold', 'unit','naira a litre', 'expected',1056.483, 'tol',0.0001),
    jsonb_build_object('key','oron_pump_price_ngn', 'label','Pump price', 'unit','naira a litre', 'expected',1243.7216, 'tol',0.0001),
    jsonb_build_object('key','oron_government_share_ngn', 'label','Government share of the pump price', 'unit','naira a litre', 'expected',73.2386, 'tol',0.0001),
    jsonb_build_object('key','oron_breakeven_fx', 'label','Exchange rate at which the pump price meets the cap', 'unit','naira to the dollar', 'expected',1682.8320980072021, 'tol',0.01)
  )
)
on conflict (app_slug, tier) do nothing;
